<?php
require_once __DIR__ . '/config.php';
function github_data_request($method,$path,$body=null){$url='https://api.github.com/repos/'.rawurlencode(GITHUB_OWNER).'/'.rawurlencode(GITHUB_REPOSITORY).'/contents/'.implode('/',array_map('rawurlencode',explode('/',trim($path,'/'))));if($method==='GET')$url.='?ref='.rawurlencode(GITHUB_BRANCH);$headers=['Accept: application/vnd.github+json','Authorization: Bearer '.GITHUB_TOKEN,'X-GitHub-Api-Version: 2022-11-28','User-Agent: ConfigBox-Admin'];$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_CONNECTTIMEOUT=>20,CURLOPT_TIMEOUT=>60]);if($body!==null){$headers[]='Content-Type: application/json';curl_setopt($c,CURLOPT_HTTPHEADER,$headers);curl_setopt($c,CURLOPT_POSTFIELDS,json_encode($body,JSON_UNESCAPED_UNICODE));}$r=curl_exec($c);$e=curl_error($c);$s=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);if($r===false||$e)throw new Exception('Falha de conexão com o GitHub: '.$e);$j=json_decode($r,true);if($s<200||$s>=300)throw new Exception(is_array($j)&&isset($j['message'])?$j['message']:'GitHub HTTP '.$s);return $j;}
function github_file_read($path){$f=github_data_request('GET',$path);$raw=base64_decode(str_replace(["\n","\r"],'',$f['content']??''),true);return ['value'=>$raw===false?[]:json_decode($raw,true),'sha'=>$f['sha']??''];}
function github_devices_read(){try{$f=github_file_read(GITHUB_DATA_FOLDER.'/'.GITHUB_DEVICES_FILE);return ['items'=>is_array($f['value'])?$f['value']:[],'sha'=>$f['sha']];}catch(Throwable $e){if(strpos($e->getMessage(),'Not Found')!==false||strpos($e->getMessage(),'HTTP 404')!==false)return['items'=>[],'sha'=>null];throw $e;}}
function github_devices_write(array $items,$sha=null){$b=['message'=>'Atualizar cadastro de aparelhos','content'=>base64_encode(json_encode(array_values($items),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)),'branch'=>GITHUB_BRANCH];if($sha)$b['sha']=$sha;return github_data_request('PUT',GITHUB_DATA_FOLDER.'/'.GITHUB_DEVICES_FILE,$b);}
function github_link_read(){try{$f=github_file_read(GITHUB_DATA_FOLDER.'/unitv-link.json');$v=$f['value'];return['url'=>is_array($v)?(string)($v['url']??''):'','sha'=>$f['sha']];}catch(Throwable $e){if(strpos($e->getMessage(),'Not Found')!==false||strpos($e->getMessage(),'HTTP 404')!==false)return['url'=>'','sha'=>null];throw $e;}}
function github_link_write($url,$sha=null){$b=['message'=>'Atualizar link do APK UniTV','content'=>base64_encode(json_encode(['url'=>$url],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)),'branch'=>GITHUB_BRANCH];if($sha)$b['sha']=$sha;return github_data_request('PUT',GITHUB_DATA_FOLDER.'/unitv-link.json',$b);}
